    #[cfg(feature = "serde")]
    #[test]
    fn food_shortage_serialization() {
        let event = Event::FoodShortage {
            empire: crate::state::EmpireId(2),
            deficit: 7,
        };
        let json = serde_json::to_string(&event).unwrap();
        let parsed: Event = serde_json::from_str(&json).unwrap();
        assert_eq!(event, parsed);
    }

